/**
 * Gateling Meetings API client — installed by `@gateling/meetings-integration`.
 *
 * @version 1.0.0 — tracks the `/api/v1` contract of https://meetings.gateling.com
 *
 * Server code only: the API key must never reach a browser. Zero dependencies;
 * `fetch` is the one on Node 18+ / Next.js. Do not edit in the consuming app —
 * upgrade with `npx shadcn@latest add @gateling/meetings-integration --overwrite`.
 */

export type MeetingsClientOptions = {
  /** `https://meetings.gateling.com` */
  baseUrl: string
  /** `gm_live_…` from /settings/integrations. */
  apiKey: string
  fetch?: typeof fetch
}

export type ExternalUser = {
  /** Your own stable id for the person (user id, staff id, …). */
  externalId: string
  name: string
  email?: string
}

export type MeetingSettings = {
  waitingRoom: boolean
  muteOnEntry: boolean
  allowGuests: boolean
  allowScreenShare: boolean
  locked: boolean
}

export type Meeting = {
  id: string
  code: string
  title: string
  status: "scheduled" | "live" | "ended"
  externalRef: string | null
  scheduledAt: string | null
  durationMinutes: number | null
  timezone: string | null
  startedAt: string | null
  endedAt: string | null
  settings: MeetingSettings
  hasPasscode: boolean
  /** The plain share link — passcode and waiting room apply. */
  guestUrl: string
  createdAt: string
}

export type CreateMeetingInput = {
  title: string
  host: ExternalUser
  /** Your handle for this meeting, e.g. `order:8812`. Searchable later. */
  externalRef?: string
  /** ISO 8601 with offset. Omit for an instant meeting. */
  scheduledAt?: string
  durationMinutes?: number
  /** IANA zone, e.g. `Africa/Cairo`. */
  timezone?: string
  passcode?: string
  settings?: Partial<MeetingSettings>
  /** Emailed an invite + .ics + reminder. */
  invitees?: string[]
}

export type UpdateMeetingInput = Partial<
  Omit<CreateMeetingInput, "host" | "invitees"> & {
    /** `""` removes the passcode. */
    passcode: string
    externalRef: string | null
  }
>

export type JoinLinkInput = {
  user: ExternalUser
  role: "host" | "participant"
  /** Seconds, 60–86400. Default 600. */
  expiresIn?: number
  /** Where "Back to <you>" points after the meeting. Must be on an allowed origin. */
  returnUrl?: string
}

export type JoinLink = {
  url: string
  role: "host" | "participant"
  expiresAt: string
  singleUse: boolean
}

export type Participant = {
  id: string
  identity: string
  displayName: string
  role: "host" | "participant"
  externalId: string | null
  joinedAt: string
  leftAt: string | null
}

export class MeetingsApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
    readonly details?: unknown,
  ) {
    super(message)
    this.name = "MeetingsApiError"
  }
}

export function createMeetingsClient({
  baseUrl,
  apiKey,
  fetch: fetchImpl = fetch,
}: MeetingsClientOptions) {
  const base = baseUrl.replace(/\/+$/, "")

  async function request<T>(
    method: string,
    path: string,
    body?: unknown,
    extraHeaders: Record<string, string> = {},
  ): Promise<T> {
    const response = await fetchImpl(`${base}/api/v1${path}`, {
      method,
      headers: {
        authorization: `Bearer ${apiKey}`,
        ...(body !== undefined ? { "content-type": "application/json" } : {}),
        ...extraHeaders,
      },
      body: body !== undefined ? JSON.stringify(body) : undefined,
    })
    if (response.status === 204) return undefined as T
    const json = (await response.json()) as
      | T
      | { error: { code: string; message: string; details?: unknown } }
    if (!response.ok) {
      const { error } = json as {
        error: { code: string; message: string; details?: unknown }
      }
      throw new MeetingsApiError(
        response.status,
        error?.code ?? "unknown",
        error?.message ?? response.statusText,
        error?.details,
      )
    }
    return json as T
  }

  return {
    /** Pass `idempotencyKey` (e.g. `order:8812:meeting`) to make retries safe. */
    async createMeeting(
      input: CreateMeetingInput,
      idempotencyKey?: string,
    ): Promise<Meeting> {
      const { meeting } = await request<{ meeting: Meeting }>(
        "POST",
        "/meetings",
        input,
        idempotencyKey ? { "idempotency-key": idempotencyKey } : {},
      )
      return meeting
    },

    async getMeeting(code: string): Promise<Meeting> {
      const { meeting } = await request<{ meeting: Meeting }>(
        "GET",
        `/meetings/${encodeURIComponent(code)}`,
      )
      return meeting
    },

    async findMeetings(filters: {
      externalRef?: string
      status?: Meeting["status"]
      limit?: number
    }): Promise<Meeting[]> {
      const query = new URLSearchParams()
      if (filters.externalRef) query.set("externalRef", filters.externalRef)
      if (filters.status) query.set("status", filters.status)
      if (filters.limit) query.set("limit", String(filters.limit))
      const { meetings } = await request<{ meetings: Meeting[] }>(
        "GET",
        `/meetings?${query}`,
      )
      return meetings
    },

    async updateMeeting(
      code: string,
      input: UpdateMeetingInput,
    ): Promise<Meeting> {
      const { meeting } = await request<{ meeting: Meeting }>(
        "PATCH",
        `/meetings/${encodeURIComponent(code)}`,
        input,
      )
      return meeting
    },

    async deleteMeeting(code: string): Promise<void> {
      await request<undefined>(
        "DELETE",
        `/meetings/${encodeURIComponent(code)}`,
      )
    },

    async endMeeting(code: string): Promise<{ status: Meeting["status"] }> {
      return request("POST", `/meetings/${encodeURIComponent(code)}/end`)
    },

    /**
     * Mint a signed link and `redirect()` the signed-in person to `url`.
     * Host links are single-use and expire in 10 minutes by default — mint
     * one per click, never store it.
     */
    async createJoinLink(
      code: string,
      input: JoinLinkInput,
    ): Promise<JoinLink> {
      const { joinLink } = await request<{ joinLink: JoinLink }>(
        "POST",
        `/meetings/${encodeURIComponent(code)}/join-links`,
        input,
      )
      return joinLink
    },

    async listParticipants(code: string): Promise<Participant[]> {
      const { participants } = await request<{ participants: Participant[] }>(
        "GET",
        `/meetings/${encodeURIComponent(code)}/participants`,
      )
      return participants
    },
  }
}

export type MeetingsClient = ReturnType<typeof createMeetingsClient>

import "server-only"

import { createMeetingsClient, type MeetingsClient } from "./client"

export * from "./client"
export * from "./scheduled-meeting"

/**
 * Environment contract shared by every Gateling system that talks to Meetings.
 * Values come from https://meetings.gateling.com/settings/integrations and are
 * shown once; "Rotate key" issues a fresh API key *and* webhook secret together.
 */
export const MEETINGS_ENV_KEYS = {
  apiUrl: "MEETINGS_API_URL",
  apiKey: "MEETINGS_API_KEY",
  webhookSecret: "MEETINGS_WEBHOOK_SECRET",
} as const

export type MeetingsEnv = {
  apiUrl: string
  apiKey: string
}

/** The URL/key pair when both are set, otherwise `null` — never a half-config. */
export function readMeetingsEnv(
  env: Record<string, string | undefined> = process.env,
): MeetingsEnv | null {
  const apiUrl = env[MEETINGS_ENV_KEYS.apiUrl]?.trim()
  const apiKey = env[MEETINGS_ENV_KEYS.apiKey]?.trim()
  if (!apiUrl || !apiKey) return null
  return { apiUrl, apiKey }
}

export function isMeetingsConfigured(): boolean {
  return readMeetingsEnv() !== null
}

let cached: { key: string; client: MeetingsClient } | null = null

/**
 * Process-wide client, or `null` when the integration is not configured so
 * callers can degrade gracefully (local dev, preview environments without
 * keys). Memoised per URL+key so a rotated key in a long-lived process is
 * picked up without a restart.
 */
export function getMeetingsClient(): MeetingsClient | null {
  const env = readMeetingsEnv()
  if (!env) return null
  const key = `${env.apiUrl}�${env.apiKey}`
  if (cached?.key !== key) {
    cached = {
      key,
      client: createMeetingsClient({ baseUrl: env.apiUrl, apiKey: env.apiKey }),
    }
  }
  return cached.client
}

import {
  type ExternalUser,
  type JoinLink,
  type Meeting,
  type MeetingSettings,
  type MeetingsClient,
  MeetingsApiError,
} from "./client"

/**
 * The orchestration every consumer repeats for an entity that "has a meeting"
 * (a booking, a lesson, a fitting, a demo): create it once, move it when the
 * entity is rescheduled, drop it when the entity is cancelled, and let the
 * right person in. Pure over the client — no database, no framework — so the
 * consuming app decides where the returned `code` and `guestUrl` are stored.
 */

export type EnsureScheduledMeetingInput = {
  /** Your handle for the entity, e.g. `booking:<uuid>`. Stable across reschedules. */
  externalRef: string
  /** The code stored from an earlier call, if any. Triggers a reschedule. */
  existingCode?: string | null
  title: string
  host: ExternalUser
  scheduledAt: Date
  durationMinutes: number
  /** IANA zone the time should be presented in, e.g. `Africa/Cairo`. */
  timezone: string
  settings?: Partial<MeetingSettings>
  passcode?: string
}

export type EnsureScheduledMeetingResult = {
  meeting: Meeting
  action: "created" | "rescheduled"
}

/**
 * Idempotency key for a create: the same entity at the same time is the same
 * meeting, so a retried job (Inngest, a double-click, a webhook replay) cannot
 * open two rooms. Meetings honours the key for 24 h.
 */
export function scheduledMeetingIdempotencyKey(
  externalRef: string,
  scheduledAt: Date,
): string {
  return `${externalRef}:${scheduledAt.toISOString()}`
}

/** A PATCH that cannot land on the old room: it was deleted or has ended. */
function isStaleMeeting(error: unknown): boolean {
  return (
    error instanceof MeetingsApiError &&
    (error.status === 404 || error.status === 412)
  )
}

/**
 * Create the meeting for `externalRef`, or move the existing one to the new
 * time. If the stored code no longer resolves (deleted, ended), a fresh room
 * is created rather than failing — the caller then overwrites its stored code.
 */
export async function ensureScheduledMeeting(
  client: MeetingsClient,
  input: EnsureScheduledMeetingInput,
): Promise<EnsureScheduledMeetingResult> {
  const scheduledAt = input.scheduledAt.toISOString()

  if (input.existingCode) {
    try {
      const meeting = await client.updateMeeting(input.existingCode, {
        title: input.title,
        scheduledAt,
        durationMinutes: input.durationMinutes,
        timezone: input.timezone,
      })
      return { meeting, action: "rescheduled" }
    } catch (error) {
      if (!isStaleMeeting(error)) throw error
    }
  }

  const meeting = await client.createMeeting(
    {
      title: input.title,
      host: input.host,
      externalRef: input.externalRef,
      scheduledAt,
      durationMinutes: input.durationMinutes,
      timezone: input.timezone,
      settings: input.settings,
      passcode: input.passcode,
    },
    scheduledMeetingIdempotencyKey(input.externalRef, input.scheduledAt),
  )
  return { meeting, action: "created" }
}

/**
 * Soft-delete the room. Returns `false` when it was already gone, which is
 * the normal outcome of a retried cancellation and not an error.
 */
export async function cancelScheduledMeeting(
  client: MeetingsClient,
  code: string,
): Promise<boolean> {
  try {
    await client.deleteMeeting(code)
    return true
  } catch (error) {
    if (error instanceof MeetingsApiError && error.status === 404) return false
    throw error
  }
}

export type JoinLinkOptions = {
  /** Where "Back to <you>" points after the meeting. Must be on an allowed origin. */
  returnUrl?: string
  /** Seconds, 60–86400. Default 600. */
  expiresIn?: number
}

/**
 * Host links are single-use and short-lived: mint one per click in a server
 * procedure and hand the URL straight to the browser. `host` must be the same
 * `externalId` the meeting was created with or Meetings answers 403.
 */
export function mintHostJoinLink(
  client: MeetingsClient,
  code: string,
  host: ExternalUser,
  options: JoinLinkOptions = {},
): Promise<JoinLink> {
  return client.createJoinLink(code, { user: host, role: "host", ...options })
}

/** Participant links skip the passcode and waiting room; reusable until expiry. */
export function mintParticipantJoinLink(
  client: MeetingsClient,
  code: string,
  user: ExternalUser,
  options: JoinLinkOptions = {},
): Promise<JoinLink> {
  return client.createJoinLink(code, { user, role: "participant", ...options })
}

import crypto from "node:crypto"

import { z } from "zod"

/**
 * Receiving side of Gateling Meetings' outbound webhooks
 * (https://meetings.gateling.com — `docs/webhooks.md`).
 *
 *   X-Meetings-Signature: t=<unix seconds>,v1=<hex hmac-sha256(secret, `${t}.${rawBody}`)>
 *
 * Verify on the raw body before parsing, reject stale timestamps so a captured
 * delivery cannot be replayed, and deduplicate on `delivery.id` — it is stable
 * across the six delivery attempts.
 */

export const MEETINGS_SIGNATURE_HEADER = "x-meetings-signature"
export const MEETINGS_EVENT_HEADER = "x-meetings-event"
export const MEETINGS_DELIVERY_HEADER = "x-meetings-delivery"

/** Five minutes: generous for clock skew, short for replay. */
export const DEFAULT_TOLERANCE_SECONDS = 5 * 60

export const meetingsWebhookEventValues = [
  "meeting.started",
  "meeting.ended",
  "participant.joined",
  "participant.left",
] as const
export type MeetingsWebhookEvent = (typeof meetingsWebhookEventValues)[number]

export const meetingsWebhookMeetingSchema = z.object({
  id: z.string(),
  code: z.string(),
  title: z.string(),
  status: z.enum(["scheduled", "live", "ended"]),
  externalRef: z.string().nullable(),
  scheduledAt: z.string().nullable(),
  startedAt: z.string().nullable(),
  endedAt: z.string().nullable(),
})

export const meetingsDeliverySchema = z.object({
  id: z.string().min(1),
  event: z.enum(meetingsWebhookEventValues),
  createdAt: z.string(),
  data: z.looseObject({
    meeting: meetingsWebhookMeetingSchema,
    at: z.string().optional(),
    endedBy: z.enum(["host", "integration", "room"]).optional(),
    participant: z
      .object({
        identity: z.string(),
        name: z.string(),
        role: z.enum(["host", "participant"]),
      })
      .optional(),
  }),
})

export type MeetingsDelivery = z.infer<typeof meetingsDeliverySchema>

export function computeMeetingsSignature(
  secret: string,
  timestamp: number,
  body: string,
): string {
  return crypto
    .createHmac("sha256", secret)
    .update(`${timestamp}.${body}`)
    .digest("hex")
}

/** Produce a valid header — for tests and for simulating deliveries locally. */
export function signMeetingsWebhook(
  secret: string,
  body: string,
  timestamp = Math.floor(Date.now() / 1000),
): string {
  return `t=${timestamp},v1=${computeMeetingsSignature(secret, timestamp, body)}`
}

export function parseMeetingsSignature(
  header: string | null | undefined,
): { timestamp: number; signature: string } | null {
  if (!header) return null
  const parts = new Map(
    header.split(",").map(part => {
      const [key, ...rest] = part.trim().split("=")
      return [key, rest.join("=")] as const
    }),
  )
  const timestamp = Number(parts.get("t"))
  const signature = parts.get("v1")
  if (!Number.isInteger(timestamp) || !signature) return null
  return { timestamp, signature }
}

/** Constant-time check of a received delivery. `now` is injectable for tests. */
export function verifyMeetingsSignature({
  secret,
  header,
  body,
  toleranceSeconds = DEFAULT_TOLERANCE_SECONDS,
  now = Math.floor(Date.now() / 1000),
}: {
  secret: string
  header: string | null | undefined
  body: string
  toleranceSeconds?: number
  now?: number
}): boolean {
  const parsed = parseMeetingsSignature(header)
  if (!parsed) return false
  if (Math.abs(now - parsed.timestamp) > toleranceSeconds) return false

  const expected = computeMeetingsSignature(secret, parsed.timestamp, body)
  const a = Buffer.from(expected, "hex")
  const b = Buffer.from(parsed.signature, "hex")
  return a.length === b.length && crypto.timingSafeEqual(a, b)
}

export type MeetingsWebhookHandlerOptions = {
  /** `MEETINGS_WEBHOOK_SECRET`. When missing the endpoint answers 503 so Meetings keeps retrying rather than dropping events. */
  secret: string | undefined
  /**
   * Called once per verified delivery. Keep it fast — enqueue to your job
   * queue and return; a slow handler is retried as if it had failed. Throwing
   * answers 500, which makes Meetings retry.
   */
  onDelivery: (delivery: MeetingsDelivery) => Promise<void> | void
  toleranceSeconds?: number
}

/**
 * A Next.js route handler (`export const POST = createMeetingsWebhookHandler(…)`)
 * that verifies, parses, hands off, and answers fast.
 */
export function createMeetingsWebhookHandler({
  secret,
  onDelivery,
  toleranceSeconds,
}: MeetingsWebhookHandlerOptions) {
  return async function POST(request: Request): Promise<Response> {
    if (!secret) {
      return Response.json(
        { error: "meetings webhook secret not configured" },
        { status: 503 },
      )
    }

    const body = await request.text()
    const header = request.headers.get(MEETINGS_SIGNATURE_HEADER)
    if (!verifyMeetingsSignature({ secret, header, body, toleranceSeconds })) {
      return Response.json({ error: "invalid signature" }, { status: 401 })
    }

    let json: unknown
    try {
      json = JSON.parse(body)
    } catch {
      return Response.json({ error: "invalid json" }, { status: 400 })
    }
    const parsed = meetingsDeliverySchema.safeParse(json)
    if (!parsed.success) {
      return Response.json({ error: "invalid delivery" }, { status: 400 })
    }

    try {
      await onDelivery(parsed.data)
    } catch {
      return Response.json({ error: "handler failed" }, { status: 500 })
    }
    return Response.json({ ok: true })
  }
}

import { describe, expect, it } from "vitest"

import { createMeetingsClient, type Meeting } from "./client"
import {
  cancelScheduledMeeting,
  ensureScheduledMeeting,
  mintHostJoinLink,
  scheduledMeetingIdempotencyKey,
} from "./scheduled-meeting"

type Recorded = {
  method: string
  path: string
  headers: Headers
  body: unknown
}

/** A fake Meetings API: scripted responses per call, every request recorded. */
function fakeApi(responses: Array<{ status: number; json?: unknown }>) {
  const calls: Recorded[] = []
  const queue = [...responses]
  const fetchImpl: typeof fetch = async (input, init) => {
    const next = queue.shift()
    if (!next) throw new Error("fake api: no scripted response left")
    calls.push({
      method: init?.method ?? "GET",
      path: new URL(String(input)).pathname,
      headers: new Headers(init?.headers),
      body: init?.body ? JSON.parse(String(init.body)) : undefined,
    })
    return new Response(
      next.status === 204 ? null : JSON.stringify(next.json ?? {}),
      { status: next.status, headers: { "content-type": "application/json" } },
    )
  }
  const client = createMeetingsClient({
    baseUrl: "https://meetings.test/",
    apiKey: "gm_live_test",
    fetch: fetchImpl,
  })
  return { client, calls }
}

const meeting: Meeting = {
  id: "m1",
  code: "abc-defg-hij",
  title: "Call",
  status: "scheduled",
  externalRef: "booking:1",
  scheduledAt: "2026-10-01T10:00:00.000Z",
  durationMinutes: 30,
  timezone: "Africa/Cairo",
  startedAt: null,
  endedAt: null,
  settings: {
    waitingRoom: true,
    muteOnEntry: false,
    allowGuests: true,
    allowScreenShare: true,
    locked: false,
  },
  hasPasscode: false,
  guestUrl: "https://meetings.test/m/abc-defg-hij",
  createdAt: "2026-09-12T00:00:00.000Z",
}

const scheduledAt = new Date("2026-10-01T10:00:00.000Z")
const base = {
  externalRef: "booking:1",
  title: "Call",
  host: { externalId: "site", name: "Site" },
  scheduledAt,
  durationMinutes: 30,
  timezone: "Africa/Cairo",
}

describe("scheduledMeetingIdempotencyKey", () => {
  it("binds the entity to the exact time", () => {
    expect(scheduledMeetingIdempotencyKey("booking:1", scheduledAt)).toBe(
      "booking:1:2026-10-01T10:00:00.000Z",
    )
  })
})

describe("ensureScheduledMeeting", () => {
  it("creates with an idempotency key when there is no existing code", async () => {
    const { client, calls } = fakeApi([{ status: 201, json: { meeting } }])

    const result = await ensureScheduledMeeting(client, base)

    expect(result.action).toBe("created")
    expect(result.meeting.code).toBe("abc-defg-hij")
    expect(calls).toHaveLength(1)
    expect(calls[0]?.method).toBe("POST")
    expect(calls[0]?.path).toBe("/api/v1/meetings")
    expect(calls[0]?.headers.get("idempotency-key")).toBe(
      "booking:1:2026-10-01T10:00:00.000Z",
    )
    expect(calls[0]?.headers.get("authorization")).toBe("Bearer gm_live_test")
    expect(calls[0]?.body).toMatchObject({
      externalRef: "booking:1",
      scheduledAt: "2026-10-01T10:00:00.000Z",
      host: { externalId: "site" },
    })
  })

  it("PATCHes the existing meeting instead of creating a second one", async () => {
    const { client, calls } = fakeApi([{ status: 200, json: { meeting } }])

    const result = await ensureScheduledMeeting(client, {
      ...base,
      existingCode: "abc-defg-hij",
    })

    expect(result.action).toBe("rescheduled")
    expect(calls).toHaveLength(1)
    expect(calls[0]?.method).toBe("PATCH")
    expect(calls[0]?.path).toBe("/api/v1/meetings/abc-defg-hij")
    expect(calls[0]?.body).toEqual({
      title: "Call",
      scheduledAt: "2026-10-01T10:00:00.000Z",
      durationMinutes: 30,
      timezone: "Africa/Cairo",
    })
  })

  it("falls through to create when the stored code no longer resolves", async () => {
    const { client, calls } = fakeApi([
      { status: 404, json: { error: { code: "not_found", message: "gone" } } },
      { status: 201, json: { meeting } },
    ])

    const result = await ensureScheduledMeeting(client, {
      ...base,
      existingCode: "old-code",
    })

    expect(result.action).toBe("created")
    expect(calls.map(c => c.method)).toEqual(["PATCH", "POST"])
  })

  it("falls through to create when the old meeting has ended", async () => {
    const { client, calls } = fakeApi([
      {
        status: 412,
        json: { error: { code: "precondition_failed", message: "ended" } },
      },
      { status: 201, json: { meeting } },
    ])

    await ensureScheduledMeeting(client, { ...base, existingCode: "old" })

    expect(calls.map(c => c.method)).toEqual(["PATCH", "POST"])
  })

  it("propagates other API errors from the PATCH", async () => {
    const { client } = fakeApi([
      { status: 401, json: { error: { code: "unauthorized", message: "no" } } },
    ])

    await expect(
      ensureScheduledMeeting(client, { ...base, existingCode: "x" }),
    ).rejects.toMatchObject({ status: 401, code: "unauthorized" })
  })
})

describe("cancelScheduledMeeting", () => {
  it("returns true on delete and false when already gone", async () => {
    const { client } = fakeApi([
      { status: 204 },
      { status: 404, json: { error: { code: "not_found", message: "gone" } } },
    ])

    expect(await cancelScheduledMeeting(client, "a")).toBe(true)
    expect(await cancelScheduledMeeting(client, "a")).toBe(false)
  })
})

describe("mintHostJoinLink", () => {
  it("requests a host-role link for the given identity", async () => {
    const { client, calls } = fakeApi([
      {
        status: 201,
        json: {
          joinLink: {
            url: "https://meetings.test/sso/join?token=t",
            role: "host",
            expiresAt: "x",
            singleUse: true,
          },
        },
      },
    ])

    const link = await mintHostJoinLink(
      client,
      "abc",
      { externalId: "site", name: "Site" },
